import { readFileSync } from 'node:fs';
const source = readFileSync('src/user.js', 'utf8');
const patch = readFileSync('change.patch', 'utf8');
const oldLine = '  console.log(\"parsing user\");';
const newLine = '  console.debug(\"parseUser called\");';
if ("'!source.includes(oldLine) || !patch.includes(`-${oldLine}`) || !patch.includes(`+${newLine}`)) throw new Error('"'Patch/source mismatch');
const patched = source.replace(oldLine, newLine);
const { parseUser } = await import("'`data:text/javascript,${encodeURIComponent(patched)}`);
const originalDebug = console.debug;
console.debug = () => {};
try {
  for (const [label, raw] of [['"'valid name', '{\"id\":1,\"name\":\" Ada \"}'], ['null name', '{\"id\":1,\"name\":null}'], ['missing name', '{\"id\":1}']]) {
